"""Shared reservation chapters for the current Word documentation set."""
from document_common import page, paragraph, read_results, table


def general(document):
    """Explain the reservation model and the acceptance example."""
    paragraph(document, 'Версия 1.2.0 дополняет учёт готовой продукции бронированием для покупателя. Документ «Бронирование продукции» создаёт резерв по организации, складу, товару и конкретной брони. Количество товара на складе при бронировании не меняется.')
    table(document, ['Операция', 'На складе, л', 'В резерве, л', 'Свободно, л'], [
        ('Исходное состояние молока',75,0,75), ('Бронь 20 л',75,20,55),
        ('Продажа этих 20 л по брони',55,0,55),
        ('Альтернативная ветвь: отмена брони без продажи',75,0,75),
    ],[3.25,1.15,1.15,1.1])
    paragraph(document, 'Свободно = На складе − В резерве. Последняя строка является альтернативой продаже, а не операцией после неё. Обычная продажа проверяется по свободному количеству; при свободных 55 л продажа 56 л отклоняется.')
    document.add_heading('Проведение и отмена',level=2)
    paragraph(document, 'Бронь формирует приход в регистр «РезервыПродукции». Продажа с реквизитом Бронирование одновременно уменьшает складской остаток и резерв этой брони. Отмена продажи возвращает товар на склад и восстанавливает резерв. После этого бронь можно отменить, чтобы количество снова стало свободным.')
    paragraph(document, 'Отмена и изменение проданной брони запрещены до отмены проведения связанной продажи. Одна бронь продаётся целиком и только один раз. При продаже проверяются организация, склад, покупатель, состав и суммарное количество товаров, а также дата. Повторяющиеся строки сравниваются суммарно.')
    document.add_heading('Целостность и права',level=2)
    paragraph(document, 'Изменения остатков и резервов выполняются в одной транзакции. Проведение и отмена получают управляемые блокировки в одинаковом порядке. В учебной реализации блокируются целиком два регистра; это упрощает защиту данных, но ограничивает параллельную работу. Нагрузочные испытания не проводились.')
    paragraph(document, 'Продажа и Полные права создают, проводят, отменяют и продают брони. Покупка видит количества резервов в отчёте остатков. Самостоятельное изменение регистра резервов пользователем не предусмотрено. Частичная отгрузка, срок действия и автоматическая отмена брони не реализованы. Непроведённый документ не резервирует товар.')


def user(document):
    """Provide the complete booking, sale and cancellation workflow."""
    page(document,'8 Бронирование продукции')
    paragraph(document,'Работайте под пользователем Продажа или Администратор. Перед началом убедитесь, что продукция поступила на нужный склад. Откройте «Остатки на складе»: для новой брони используется колонка «Свободно», а не весь складской остаток.')
    for index,text in enumerate([
        'В разделе Продажа нажмите «Забронировать продукцию». Укажите дату, организацию, склад и покупателя.',
        'Добавьте продукцию. Для проверки исходного примера выберите молоко, количество 20 л, цену 90 руб. Сумма брони составит 1 800 руб.',
        'Нажмите «Провести». Для дальнейших действий оставьте карточку открытой либо откройте документ из «Журнала бронирований». Простая запись без проведения не создаёт резерв.',
        'Сформируйте отчёт на дату не раньше брони: на складе 75 л, в резерве 20 л, свободно 55 л. Обычную продажу 56 л система отклонит.',
        'Для выдачи товара нажмите «Продать по брони». Команда сразу создаёт и проводит расход на всю бронь, затем открывает его. Склад уменьшится до 55 л, резерв станет нулевым. Нажимать кнопку обычного создания продажи дополнительно не нужно.',
        'Если выдачи не было, вместо продажи нажмите «Отменить бронь». На складе останется 75 л, резерв станет нулевым, свободно снова будет 75 л.',
    ],1): paragraph(document,f'{index}. {text}')
    document.add_heading('Если нужно исправить проданную бронь',level=2)
    paragraph(document,'Откройте связанный Расход в журнале продаж и отмените его проведение. Это возвращает 20 л на склад и в резерв, поэтому свободно остаётся 55 л. Затем отмените бронь: свободно станет 75 л. Чтобы снова выдать товар, проведите бронь и оформите продажу по ней.')
    table(document,['Ситуация','Действие'],[
        ('Недостаточно свободной продукции','Проверьте организацию, склад, проведённые брони и колонку Свободно. Уменьшите количество либо освободите ненужную бронь.'),
        ('Бронь продана','Откройте существующий Расход. Для исправления сначала отмените его проведение.'),
        ('Есть несохранённые изменения','Запишите и проведите бронь либо закройте карточку без сохранения и откройте заново.'),
        ('Не совпадают реквизиты или количество','Используйте «Продать по брони». Вручную созданный Расход должен ссылаться на бронь и включать весь её состав.'),
    ],[2.2,4.45])
    paragraph(document,'Повторное проведение не удваивает резерв. Повторная продажа той же брони отклоняется. Бронь действует до продажи или отмены: автоматического истечения срока и частичной продажи нет. Контрольный пример выполняйте в отдельной копии базы; после демонстрации отмените созданные тестовые документы.')


def design(document):
    """Record the additional UI decisions for booking operations."""
    page(document,'6 Оформление бронирования')
    paragraph(document,'Новые команды размещены в разделе Продажа и на общем рабочем столе для пользователей с правами продажи. «Забронировать продукцию» создаёт документ, «Журнал бронирований» открывает список. Используется прежняя зелёная палитра; назначения действий указаны словами.')
    table(document,['Элемент','Решение и причина'],[
        ('Карточка бронирования','Те же поля и таблица продукции, что в продаже: пользователь переносит знакомый порядок заполнения.'),
        ('Состояние','Отдельное поле только для просмотра: Забронирована, Продана либо Не действует. Состояние определяется проведением и связанной продажей.'),
        ('Продать по брони','Явная команда в карточке. Создаёт и проводит один Расход на весь резерв, затем открывает результат.'),
        ('Отменить бронь','Отдельная подписанная команда; не заменяется удалением строк или отрицательным количеством.'),
        ('Отчёт остатков','Три раздельные колонки: НаСкладе, ВРезерве и Свободно. Цвет не используется как единственный признак доступности товара.'),
    ],[2.0,4.65])
    paragraph(document,'Снимки старого рабочего стола и прежнего отчёта в этом документе иллюстрируют расположение групп и палитру до доработки. Они не показывают новые кнопки и колонки. Создание новых элементов и вызов обработчиков подтверждены BF01–BF06; удобство мыши, масштабирование требуют ручного осмотра. Печать заблокирована учебной лицензией.')


def testing(document):
    """Add traceable booking acceptance scenarios from the actual test logs."""
    checks=read_results('reservation-tests.txt')
    assert len(checks)==28
    expected=[
        'Склад 75; резерв 20; свободно 55', 'Резерв 20', 'Отказ', 'Склад 75; резерв 20',
        'Отказ', 'Отказ', 'Склад 20; резерв 20; свободно 0', 'Склад 75; резерв 20',
        'Отказ', 'Отказ', 'Отказ', 'Отказ', 'Отказ', 'Склад 75; резерв 0; свободно 75',
        'Отказ', 'Резерв 0', 'Склад 55; резерв 0; свободно 55', 'Продана',
        'Склад 55; резерв 0', 'Отказ', 'Отказ', 'Отказ', 'Склад 75; резерв 20',
        'Склад 75; резерв 0', 'Отказ', 'Отказ', 'Резерв 75; свободно 0', 'Отказ',
    ]
    for start,end,title in [(0,14,'6 Бронирование: создание и отмена'),(14,28,'7 Бронирование: продажа и восстановление')]:
        page(document,title)
        paragraph(document,'Протокол reservation-tests.txt. Изолированные организация и склад, молоко по 90 руб./л, начальный складской остаток 75 л. Проверки выполняются последовательно; временные документы удалены после прогона. В таблице приведены ожидаемые значения, совпавшие с фактическими.')
        rows=[]
        for index in range(start,end):
            code,action=checks[index].split(' ',1)
            rows.append((code,action,expected[index],'Совпало'))
        table(document,['Код','Действие и условие','Ожидается','Факт'],rows,[.45,3.05,2.3,.85])
    page(document,'8 Команды брони и приёмка доработки')
    forms=read_results('reservation-form-tests.txt')
    assert len(forms)==6
    table(document,['Код','Проверка','Ожидаемый и фактический результат'],[
        ('BF01','Создание карточки проведённой брони','Есть команды продажи и отмены; состояние Забронирована.'),
        ('BF02','Вызов Продать по брони','Создан и проведён Расход; состояние Продана.'),
        ('BF03','Повторный вызов продажи','Отказ; вторая проведённая продажа не создана.'),
        ('BF04','Отмена продажи, затем команда отмены брони','Бронь перестала действовать; резерв снят.'),
        ('BF05','Формирование остатков','Есть колонки НаСкладе, ВРезерве, Свободно.'),
        ('BF06','Создание страницы Продажа','Есть команды создания и журнала броней.'),
    ],[.55,2.55,3.55])
    paragraph(document,'Все шесть сценариев вызывают обработчики управляемых форм программно. Это проверка кода команд, а не воспроизведение щелчков мышью. Результаты сохранены в reservation-form-tests.txt. Права дополнены R08 (проведение брони только Продажей) и R09 (чтение резервов обеими рабочими ролями).')
    document.add_heading('Быстрая ручная демонстрация',level=2)
    paragraph(document,'Покажите исходные 75 л → бронь 20 л и свободные 55 л → отказ обычной продажи 56 л. Затем выполните две отдельные ветви: отмена брони возвращает свободные 75 л; продажа по брони оставляет на складе и в свободном остатке 55 л. Для повторения верните базу к исходному состоянию.')
    paragraph(document,'Дополнительно проверьте команды мышью, подписи состояния после записи, видимость новых колонок. Печать и сохранение табличного документа недоступны в установленной учебной версии. Многопользовательское одновременное бронирование нагрузочным тестом не проверялось. Ограничения доработки: целая бронь, один покупатель, один склад, без автоматического срока действия.')
